                + " * Clamps a value. Returns low when value is smaller.\n"
                + " *\n"
                + " * Used by the layout code.\n"
                + " *\n"
                + " * @param value the input\n"
                + " * @return the clamped value\n"
                + " */";
        String oneLine = "/** Resets the counter. */";
        String noPeriod = "/**\n * Holds a colour\n */";
        String tagsOnly = "/**\n * @param seed the seed\n */";

        check("description joins the prose lines",
                "Clamps a value. Returns low when value is smaller. Used by the layout code.",
                DocCommentCleaner.descriptionOf(full));
        check("first sentence", "Clamps a value.", DocCommentCleaner.firstSentence(full));
        check("one line comment", "Resets the counter.", DocCommentCleaner.descriptionOf(oneLine));
        check("one line first sentence", "Resets the counter.", DocCommentCleaner.firstSentence(oneLine));
        check("no period keeps everything", "Holds a colour", DocCommentCleaner.firstSentence(noPeriod));
