public class DocCommentCleaner {

    public static String descriptionOf(String docComment) {
        if (docComment == null) {
            return "";
        }
        StringBuilder text = new StringBuilder();
        for (String raw : docComment.split("\n", -1)) {
            String line = clean(raw);
            if (line.startsWith("@")) {
                break;
            }
            if (text.length() > 0) {
                text.append(' ');
            }
            text.append(line);
        }
        return text.toString().replaceAll(" +", " ").trim();
    }

    public static String firstSentence(String docComment) {
        String description = descriptionOf(docComment);
        for (int i = 0; i < description.length(); i++) {
            if (description.charAt(i) != '.') {
                continue;
            }
            if (i == description.length() - 1 || description.charAt(i + 1) == ' ') {
                return description.substring(0, i + 1);
            }
        }
        return description;
    }

    private static String clean(String raw) {
        String line = raw.trim();
        if (line.startsWith("/**")) {
            line = line.substring(3).trim();
        }
        if (line.endsWith("*/")) {
            line = line.substring(0, line.length() - 2).trim();
        }
        if (line.startsWith("*")) {
            line = line.substring(1).trim();
        }
        return line.trim();
    }
}
